    if (!r.width || !r.height) return [this.camera.x, this.camera.y];
    const c = this.camera;
    const x = c.x + ((px - r.left) / r.width - 0.5) * c.w / c.zoom;
    const y = c.y - ((py - r.top) / r.height - 0.5) * c.h / c.zoom;
